        yield return ["nonconfigurable-proxy-invariants", "const owner:any=Promise,s=Symbol.species;Object.defineProperty(owner,s,{configurable:false});console.log(Reflect.deleteProperty(owner,s),Object.hasOwn(owner,s));function strictDelete(){\"use strict\";try{delete owner[s];console.log(\"deleted\");}catch(error){console.log(error instanceof TypeError);}}strictDelete();for(const handler of [{ownKeys(){return[];}},{getOwnPropertyDescriptor(){return undefined;}},{has(){return false;}}]){const proxy:any=new Proxy(owner,handler);try{if(\"ownKeys\"in handler)Reflect.ownKeys(proxy);else if(\"has\"in handler)Reflect.has(proxy,s);else Object.getOwnPropertyDescriptor(proxy,s);console.log(\"accepted\");}catch(error){console.log(error instanceof TypeError);}}", "false true\ntrue\ntrue\ntrue\ntrue\n"];
