    [Theory, MemberData(nameof(Cases))]
    public void PhysicalDescriptorAndReceiverProtocols(string name, string source, string expected)
    {
        Assert.NotEmpty(name);
        Assert.Equal(expected, TestHarness.RunInterpreted(source));
    }

    [Fact]
    public void SymbolDescriptorsAndIntegrityRemainRealmLocal()
    {
        Assert.Equal("true\n", TestHarness.RunInterpreted("Object.freeze(Promise);console.log(Object.isFrozen(Promise));"));
        Assert.Equal("true true\n", TestHarness.RunInterpreted("console.log(Object.isExtensible(Promise),Object.getOwnPropertyDescriptor(Promise,Symbol.species)!.configurable);"));
        Assert.Equal("true\n", TestHarness.RunInterpreted("console.log(delete (Promise as any)[Symbol.species]);"));
        Assert.Equal("function\n", TestHarness.RunInterpreted("console.log(typeof Object.getOwnPropertyDescriptor(Promise,Symbol.species)!.get);"));
    }
}
